INSERT INTO videos (id, url, title, thumbnailUrl, platform, categoryId, createdAt) VALUES ('1774572360003', 'https://vt.tiktok.com/ZSuEd2EAp/', 'Hot Honey Chicken Tenders ✨🔥 Ingredientes — Pechuga de pollo en tiras — Sal y pimienta — Paprika — Ajo en polvo — Harina de trigo — Maicena — Polvo para hornear Rexal — Huevo — Agua mineral fría — Salsa búfalo Para la hot honey — Mantequilla — Miel — Salsa búfalo — Vinagre de manzana — Salsa inglesa — Paprika — Soya Paso a paso \t1.\tSazona las tiras de pechuga con sal, pimienta, paprika y ajo en polvo. Integra perfectamente y deja reposar unos minutos. \t2.\tEn un bowl mezcla la harina, maicena y polvo para hornear. Incorpora el huevo, el agua mineral fría y la salsa búfalo hasta obtener una mezcla ligera, aireada y ligeramente espesa. \t3.\tPasa el pollo primero por harina, luego por la mezcla líquida y nuevamente por harina para crear esa capa crujiente y bien estructurada. \t4.\tFríe en aceite a fuego medio–bajo hasta que estén dorados, inflados y perfectamente cocidos por dentro. Retira y deja escurrir. \t5.\tPara la hot honey, derrite la mantequilla y agrega miel, salsa búfalo, vinagre de manzana, salsa inglesa, paprika y un toque de soya. Cocina a fuego bajo hasta que emulsione y se vuelva brillante. \t6.\tBaña los tenders recién fritos o sirve la salsa aparte para dippear generosamente. Crujientes. Picantes. Dulces. Equilibrados. Pura comedera, pura gozadera. 🍯🔥  #comida #tenders #foodie #recetas ', 'https://p16-sign-sg.tiktokcdn.com/tos-alisg-p-0037/o4yEeEyDgPPBHWUFftpRBEA5Q7E74oQpmvwdcU~tplv-tiktokx-origin.image?dr=14575&x-expires=1774742400&x-signature=Z2q2QQdGM0Yyw1PyXZa9zb143VI%3D&t=4d5b0474&ps=13740610&shp=81f88b70&shcp=43f4a2f9&idc=my3', 'tiktok', '1773533002798', 1774572360003);
